// Builds apps/web/src/legal/texts.generated.ts from docs/legal, so the app shows the same text
// that is reviewed in the repository (Q-ACC-3). Run `pnpm legal:build` after editing a text;
// build.test.ts fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "../..");
export const OUTPUT = "apps/web/src/legal/texts.generated.ts";

export const SOURCES = {
  terms: "docs/legal/terms-of-use.md",
  privacy: "docs/legal/privacy-notice.md",
} as const;

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

/** "Version 0.1 · Draft · 1 October 2026" → version, draft flag and ISO date. */
export function parseHeader(markdown: string, source: string) {
  const match = /^Version (\d+\.\d+) · (?:(Draft) · )?(\d{1,2}) ([A-Z][a-z]+) (\d{4})$/m.exec(
    markdown,
  );
  const month = match ? MONTHS.indexOf(match[4] ?? "") + 1 : 0;
  if (!match || month === 0)
    throw new Error(`${source}: missing "Version … · day Month year" line`);
  const day = String(match[3]).padStart(2, "0");
  return {
    version: match[1] as string,
    draft: match[2] === "Draft",
    published: `${match[5]}-${String(month).padStart(2, "0")}-${day}`,
  };
}

export interface LegalText {
  id: keyof typeof SOURCES;
  path: string;
  version: string;
  draft: boolean;
  published: string;
  markdown: string;
}

/** The texts the app ships, read from docs/legal. */
export function readLegalTexts(read: (path: string) => string): LegalText[] {
  return Object.entries(SOURCES).map(([id, path]) => {
    const markdown = read(path);
    return { id: id as LegalText["id"], path, ...parseHeader(markdown, path), markdown };
  });
}

export function buildLegalModule(read: (path: string) => string): string {
  const entries = readLegalTexts(read).map(({ id, markdown, ...header }) => {
    return `  ${id}: {
    version: ${JSON.stringify(header.version)},
    draft: ${header.draft},
    published: ${JSON.stringify(header.published)},
    markdown: ${JSON.stringify(markdown)},
  },`;
  });
  return `// Generated by tools/legal/build.ts from docs/legal. Do not edit; run \`pnpm legal:build\`.
export const LEGAL_TEXTS = {
${entries.join("\n")}
} as const;

export type LegalTextId = keyof typeof LEGAL_TEXTS;
`;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const output = buildLegalModule((path) => readFileSync(join(ROOT, path), "utf8"));
  writeFileSync(join(ROOT, OUTPUT), output);
  console.log(`Wrote ${OUTPUT}`);
}
